278	/**
279	 * Deletes an existing knowledge insight identified by its numeric ID.
280	 *
281	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
282	 * for non-integer, zero, or floating-point strings). Requires `scope` as a
283	 * query parameter; when `scope === 'repository'`, `repository_name` is also required
284	 * (throws VALIDATION_ERROR if absent). Scopes the deletion to the correct store
285	 * to prevent accidental cross-scope deletion when the same numeric ID exists in
286	 * multiple stores.
287	 *
288	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
289	 *
290	 * `repository_name` is validated against `PROJECT_SLUG_REGEX` at this handler level
291	 * (after the presence check) before being forwarded to the storage layer. A malformed
292	 * slug throws `VALIDATION_ERROR` (HTTP 400) immediately, consistent with
293	 * `handleMoveKnowledge` and `handleUpdateKnowledge`.
294	 *
295	 * @param ledgerRoot      Absolute path to the central ledger root.
296	 * @param rawId           Raw ID string from the URL parameter (e.g. "42").
297	 * @param scope           Required scope query parameter ('global' or 'repository').
298	 * @param repository_name Required when scope is 'repository'; the repository name.
299	 * @returns `null` — consistent with other delete handlers.
300	 */
301	export async function handleDeleteKnowledge(
302	  ledgerRoot: string,
303	  rawId: string,
304	  scope: string | undefined,
305	  repository_name?: string
306	): Promise<null> {
307	  const id = parseKnowledgeId(rawId);
308	
309	  // Validate scope — required and must be a recognised InsightScope value.
310	  const scopeResult = InsightScope.safeParse(scope);
311	  if (!scopeResult.success) {
312	    validationError('scope query parameter is required and must be "global" or "repository".');
313	  }
314	  const validatedScope = scopeResult.data;
315	
316	  // repository_name is required when scope === 'repository'.
317	  if (validatedScope === 'repository' && !repository_name) {
318	    validationError('repository_name query parameter is required when scope is "repository".');
319	  }
320	
321	  // Validate repository_name format — must match PROJECT_SLUG_REGEX.
322	  if (repository_name && !PROJECT_SLUG_REGEX.test(repository_name)) {
323	    validationError('repository_name contains invalid characters. Use only alphanumerics, hyphens, and underscores.');
324	  }
325	
326	  const manager = new KnowledgeStoreManager(ledgerRoot);
327	
328	  try {
329	    await manager.deleteInsight(id, { scope: validatedScope, repository_name });
330	  } catch (err) {
331	    const msg = err instanceof Error ? err.message : String(err);
332	    if (msg.includes('not found')) {
333	      throw new ApiError('NOT_FOUND', 'Insight not found.');
334	    }
335	    throw err;
336	  }
337	
338	  return null;
339	}
