345	/**
346	 * Promotes a repository-scoped insight to global scope using the atomic
347	 * KnowledgeStoreManager.moveInsight() method.
348	 *
349	 * The returned insight is the newly created global-scoped copy — it has a
350	 * **different numeric ID** than the original (assigned by the global store's

351	 * `next_id` counter). The frontend must match by pre-promote ID, not the new ID.
352	 *
353	 * `repository_name` is validated against `PROJECT_SLUG_REGEX` at this handler level
354	 * (after the presence check) before being forwarded to the storage layer. A malformed
355	 * slug throws `VALIDATION_ERROR` (HTTP 400) immediately, consistent with
356	 * `handleMoveKnowledge` and `handleUpdateKnowledge`.
357	 *
358	 * @param ledgerRoot      Absolute path to the central ledger root.
359	 * @param rawId           Raw ID string from the URL parameter (e.g. "42").
360	 * @param scope           Source scope — must be "repository" (global insights cannot be promoted).
361	 * @param repository_name Required when scope is "repository"; the source repository name.
362	 * @returns The newly created global Insight.
363	 * @throws ApiError VALIDATION_ERROR if scope is not "repository", insight is already global,
364	 *   or repository_name fails PROJECT_SLUG_REGEX validation.
365	 * @throws ApiError NOT_FOUND if no matching insight exists in the specified scope.
366	 */
367	export async function handlePromoteKnowledge(
368	  ledgerRoot: string,
369	  rawId: string,
370	  scope: string | undefined,
371	  repository_name?: string
372	): Promise<Insight> {
373	  const id = parseKnowledgeId(rawId);
374	
375	  // Validate scope — must be 'repository' (global insights are already global).
376	  const scopeResult = InsightScope.safeParse(scope);
377	  if (!scopeResult.success) {
378	    validationError('scope query parameter is required and must be "global" or "repository".');
379	  }
380	  const validatedScope = scopeResult.data;
381	
382	  if (validatedScope === 'global') {
383	    validationError('Insight is already global and cannot be promoted.');
384	  }
385	
386	  // repository_name is required when scope === 'repository'.
387	  if (!repository_name) {
388	    validationError('repository_name query parameter is required when scope is "repository".');
389	  }
390	
391	  // Validate repository_name format — must match PROJECT_SLUG_REGEX.
392	  if (!PROJECT_SLUG_REGEX.test(repository_name)) {
393	    validationError('repository_name contains invalid characters. Use only alphanumerics, hyphens, and underscores.');
394	  }
395	
396	  const manager = new KnowledgeStoreManager(ledgerRoot);
397	
398	  try {
399	    return await manager.moveInsight(
400	      id,
401	      { scope: validatedScope, repository_name },
402	      'global'
403	    );
404	  } catch (err) {
405	    const msg = err instanceof Error ? err.message : String(err);
406	    if (msg.toLowerCase().includes('not found')) {
407	      throw new ApiError('NOT_FOUND', 'Insight not found.');
408	    }
409	    throw err;
410	  }
411	}
